from __future__ import annotations
import csv, hashlib, json
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parent
R=ROOT/'research_v60'

def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def loadj(rel):return json.loads((ROOT/rel).read_text())
def count_csv(rel):
    with (ROOT/rel).open(newline='',encoding='utf-8') as f:return sum(1 for _ in csv.DictReader(f))
def bool_count(rel,col):
    with (ROOT/rel).open(newline='',encoding='utf-8') as f:return sum(str(r.get(col,'')).lower() in {'true','1'} for r in csv.DictReader(f))

